import{_ as i,o as e,c as I,a0 as l}from"./chunks/framework.DQOulFGV.js";const a="data:image/svg+xml;base64,",s="data:image/svg+xml;base64,",r=JSON.parse('{"title":"第2章 阻塞与故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"redis/05-operations/chapter-02-troubleshooting.md","filePath":"redis/05-operations/chapter-02-troubleshooting.md"}'),d={name:"redis/05-operations/chapter-02-troubleshooting.md"};function g(n,t,h,y,m,c){return e(),I("div",null,[...t[0]||(t[0]=[l(`<h1 id="第2章-阻塞与故障排查" tabindex="-1">第2章 阻塞与故障排查 <a class="header-anchor" href="#第2章-阻塞与故障排查" aria-label="Permalink to &quot;第2章 阻塞与故障排查&quot;">​</a></h1><blockquote><p>线上 Redis 变慢或异常，需要一套系统的方法快速定位根因。本章介绍排查工具与常见故障的定位思路。</p></blockquote><hr><h2 id="_2-1-排查工具" tabindex="-1">2.1 排查工具 <a class="header-anchor" href="#_2-1-排查工具" aria-label="Permalink to &quot;2.1 排查工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">工具</th><th style="text-align:left;">用途</th></tr></thead><tbody><tr><td style="text-align:left;"><code>INFO</code></td><td style="text-align:left;">查看服务器状态全貌（stats/memory/clients/commandstats）</td></tr><tr><td style="text-align:left;"><code>SLOWLOG</code></td><td style="text-align:left;">查看慢查询日志</td></tr><tr><td style="text-align:left;"><code>MONITOR</code></td><td style="text-align:left;">实时观察命令流（有性能开销，慎用）</td></tr><tr><td style="text-align:left;"><code>CLIENT LIST</code></td><td style="text-align:left;">查看客户端连接详情</td></tr><tr><td style="text-align:left;"><code>redis-cli --latency</code></td><td style="text-align:left;">测试网络延迟</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commandstats</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 各命令的调用统计与耗时</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 内存使用、碎片率</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CLIENT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LIST</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 连接数、每个客户端状态</span></span></code></pre></div><hr><h2 id="_2-2-延迟突增" tabindex="-1">2.2 延迟突增 <a class="header-anchor" href="#_2-2-延迟突增" aria-label="Permalink to &quot;2.2 延迟突增&quot;">​</a></h2><p>延迟突增是最常见的故障，按顺序排查：</p><p><img src="`+a+`" alt="延迟排查顺序"></p><table tabindex="0"><thead><tr><th style="text-align:left;">排查点</th><th style="text-align:left;">说明</th><th style="text-align:left;">判断方法</th></tr></thead><tbody><tr><td style="text-align:left;">慢命令</td><td style="text-align:left;">慢查询日志有耗时命令</td><td style="text-align:left;"><code>SLOWLOG GET</code></td></tr><tr><td style="text-align:left;">fork 停顿</td><td style="text-align:left;">BGSAVE/AOF 重写引发</td><td style="text-align:left;"><code>INFO stats</code> 的 <code>latest_fork_usec</code></td></tr><tr><td style="text-align:left;">fsync 阻塞</td><td style="text-align:left;">AOF <code>always</code> 刷盘慢</td><td style="text-align:left;">磁盘 IO 监控</td></tr><tr><td style="text-align:left;">swap</td><td style="text-align:left;">内存被换出到磁盘</td><td style="text-align:left;"><code>INFO memory</code> 的 <code>used_memory_rss</code> 与 swap</td></tr></tbody></table><hr><h2 id="_2-3-内存异常" tabindex="-1">2.3 内存异常 <a class="header-anchor" href="#_2-3-内存异常" aria-label="Permalink to &quot;2.3 内存异常&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">现象</th><th style="text-align:left;">可能原因</th><th style="text-align:left;">排查</th></tr></thead><tbody><tr><td style="text-align:left;">内存持续增长</td><td style="text-align:left;">key 无 TTL 堆积</td><td style="text-align:left;"><code>INFO keyspace</code> 看 key 数量</td></tr><tr><td style="text-align:left;">碎片率高</td><td style="text-align:left;">频繁增删 key</td><td style="text-align:left;"><code>INFO memory</code> 的 <code>mem_fragmentation_ratio</code></td></tr><tr><td style="text-align:left;">使用了 swap</td><td style="text-align:left;">内存超物理上限</td><td style="text-align:left;"><code>used_memory_rss</code> &gt; 物理内存</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># used_memory            实际使用内存</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># used_memory_rss        操作系统分配内存</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># mem_fragmentation_ratio 碎片率</span></span></code></pre></div><hr><h2 id="_2-4-cpu-飙升" tabindex="-1">2.4 CPU 飙升 <a class="header-anchor" href="#_2-4-cpu-飙升" aria-label="Permalink to &quot;2.4 CPU 飙升&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">排查点</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>INFO commandstats</code></td><td style="text-align:left;">找出调用频繁、耗时高的命令</td></tr><tr><td style="text-align:left;">Lua 长脚本</td><td style="text-align:left;">脚本执行期间独占 CPU</td></tr><tr><td style="text-align:left;">频繁 BGSAVE</td><td style="text-align:left;">fork 与 COW 消耗 CPU</td></tr><tr><td style="text-align:left;">过期键过多</td><td style="text-align:left;">定期删除扫描消耗 CPU</td></tr></tbody></table><hr><h2 id="_2-5-连接数异常" tabindex="-1">2.5 连接数异常 <a class="header-anchor" href="#_2-5-连接数异常" aria-label="Permalink to &quot;2.5 连接数异常&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">现象</th><th style="text-align:left;">可能原因</th><th style="text-align:left;">排查</th></tr></thead><tbody><tr><td style="text-align:left;">连接数过高</td><td style="text-align:left;">连接池泄漏、短连接</td><td style="text-align:left;"><code>CLIENT LIST</code> 统计</td></tr><tr><td style="text-align:left;">连接被拒</td><td style="text-align:left;">达到 maxclients 上限</td><td style="text-align:left;"><code>CONFIG GET maxclients</code></td></tr><tr><td style="text-align:left;">TIME_WAIT 堆积</td><td style="text-align:left;">频繁短连接</td><td style="text-align:left;">系统层面 <code>ss -s</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CONFIG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maxclients</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 查看最大连接数</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CLIENT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LIST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 统计当前连接数</span></span></code></pre></div><hr><h2 id="_2-6-排查方法论" tabindex="-1">2.6 排查方法论 <a class="header-anchor" href="#_2-6-排查方法论" aria-label="Permalink to &quot;2.6 排查方法论&quot;">​</a></h2><p>一套可复用的排查流程：</p><p><img src="`+s+'" alt="排查方法论循环"></p><p>要点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">步骤</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">观察现象</td><td style="text-align:left;">明确是延迟、内存还是 CPU 问题</td></tr><tr><td style="text-align:left;">收集指标</td><td style="text-align:left;">用 INFO、SLOWLOG 收集客观数据</td></tr><tr><td style="text-align:left;">提出假设</td><td style="text-align:left;">基于指标缩小范围</td></tr><tr><td style="text-align:left;">验证假设</td><td style="text-align:left;">用数据证实或推翻，不凭直觉</td></tr></tbody></table>',28)])])}const Z=i(d,[["render",g]]);export{r as __pageData,Z as default};
